1	/**
2	 * Benny — the ONE canonical mascot model + joint rig (procedural, exported to assets/models/benny.glb).
3	 *
4	 * Contract: origin = centre of the round body, faces +Z, up +Y. Skin sphere r = 0.70 (lower half bulged
5	 * ~6 % → pear-round plush ball), fur adds ~0.15 (visual half-width ≈ 0.86). The beanie perches on the
6	 * top ~40 % of the ball (brim bottom ≈ +0.10 at the back, +0.24 at the front). Height incl. pom ≈ 2.3.
7	 * Joints: benny_root › body › { hat › pom, eyes › eyeL/eyeR, mouth, armL, armR, footL, footR }.
8	 * Meshes named fur_* receive the runtime shell-fur shader (see fur.ts); their userData carries the
9	 * fur parameters (exported as glTF extras).
10	 */
11	import * as THREE from 'three';
12	import type { BuiltModel } from '../types';
13	import {
14	  BENNY_COLORS as C,
15	  CROWN_REPEAT,
16	  blushTexture,
17	  eyeTexture,
18	  knitCrownTextures,
19	  mouthTexture,
20	  ribbedBrimTextures,
21	  soleTexture,
22	} from './textures';
23	
24	export const BENNY_DIMS = {
25	  skin: 0.7,
26	  fur: 0.12,
27	  radius: 0.8,
28	  /** lower-body bulge (radial gain at its peak): a full round plush ball below the cuff, not a bowl (ref 05 rear:
29	   *  body ≈ as wide as the cuff from the cuff down to the water) */
30	  pear: 0.1,
31	  /** centre (below the ball centre) and width of that bulge */
32	  bulgeY: 0.24,
33	  bulgeW: 0.38,
34	  /** fuller, flatter bottom (wave 5, ref 05 rear: the plush ball stays ≈ cuff-wide down to the waterline and ends
35	   *  in a broad round base, not an egg tip). Lower-half cross-section r_xz = r·(1 − t^p)^(1/p), t = −y/r,
36	   *  p = 2 + flat (0 = sphere), radial gain capped at flatCap. Lab g05 rows 1129/1149/1169: 247/208/143 px (sphere)
37	   *  → 259/234/176 (ref 05: 258/228/181) */
38	  flat: 0.8,
39	  flatCap: 1.5,
40	  /** lower-half vertical stretch at the bottom pole (y' = y·(1 + stretch·|y|/r) for y < 0). Wave 5: 0.10 → 0.03 with
41	   *  the flatter base (keeps the bottom at the ref-05 waterline, ≈ 1185 px) */
42	  stretch: 0.03,
43	  /** beanie tilt (rad, about X; + = front down). Wave 4: back to a slight backward tilt so the front brim clears the
44	   *  eyes (refs 02/03); the rear ride views get their low, level look from the runtime's ride lean instead
45	   *  (runtime.ts BENNY_RIDE_PITCH), not from tipping the hat over his face */
46	  hatTilt: -0.04,
47	  /** hat-local cuff bottom (front ≈ +0.25, back ≈ +0.19 above the ball centre). Wave 4: the beanie sits DOWN on the
48	   *  head again (wave 3's 0.40 perched it like a small cap and pushed the pom 60 px above the ref) */
49	  brimBottom: 0.22,
50	  /** cuff outer radius ≈ the fluffy body half-width (rear refs 05/07/09/10: cuff as wide as the body) */
51	  brimR: 0.8,
52	  /** folded cuff band height (ref 05: 55 px band on a 295 px wide cuff) */
53	  cuffH: 0.265,
54	  /** crown dome height above its base (inside the cuff). Wave 4: taller rounded dome (ref 05 rear: ≈ 95 px of knit
55	   *  between the cuff and the pom, the old 0.44 showed 76 px) */
56	  crownH: 0.53,
57	  /** pom-pom core radius; the shell fur adds ≈ 0.1 → ≈ 0.5 × the cuff width (ref 05: ≈ 140–150 px / 295) */
58	  pomR: 0.31,
59	  /** star badge: angle around the hat from the front (deg, toward −X = his right), centre height above the cuff
60	   *  top, centre radius. Wave 5: 143° / +0.015 / 0.79 → 137° / +0.065 / 0.77 (live 05: centre (500, 965) = +0.57 cuff
61	   *  half-widths; ref 05: (519, 953) = +0.64, lower points on the cuff, the rest on the white band) */
62	  starAng: 137,
63	  starY: 0.065,
64	  starR: 0.77,
65	};
66	
67	/**
68	 * Body skin deformation of a point `v` on the r = skin sphere: the lower half is stretched down a little
69	 * and bulged radially (strongest at the sides/back, faded out on the face so eyes, blush and mouth keep
70	 * their places) → a big round plush ball below the beanie.
71	 */
72	function deformBody(v: THREE.Vector3, out: THREE.Vector3): THREE.Vector3 {
73	  const D = BENNY_DIMS;
74	  const r = D.skin;
75	  const zf = THREE.MathUtils.smoothstep(v.z / r, 0.1, 0.75);
76	  const face = 1 - 0.8 * zf;
77	  let k = 1 + D.pear * Math.exp(-(((v.y + D.bulgeY) / D.bulgeW) ** 2)) * face;
78	  k *= 1 + (bottomGain(-v.y / r) - 1) * face;
79	  const y = v.y < 0 ? v.y * (1 + (D.stretch * -v.y) / r) : v.y;
80	  return out.set(v.x * k, y, v.z * k);
81	}
82	
83	/** radial gain of the flattened lower half at t = −y/r (1 on the upper half / with flat = 0) */
84	function bottomGain(t: number): number {
85	  const D = BENNY_DIMS;
86	  if (D.flat <= 0 || t <= 0) return 1;
87	  const tc = Math.min(t, 0.9999);
88	  const p = 2 + D.flat;
89	  return Math.min(D.flatCap, Math.pow(1 - Math.pow(tc, p), 1 / p) / Math.sqrt(1 - tc * tc));
90	}
91	
92	const FACE_DIR = new THREE.Vector3(0, 0.05, 1).normalize();
93	
94	function named<T extends THREE.Object3D>(o: T, name: string): T {
95	  o.name = name;
96	  return o;
97	}
98	
99	function joint(name: string, x = 0, y = 0, z = 0): THREE.Object3D {
100	  const j = new THREE.Object3D();
101	  j.name = name;
102	  j.position.set(x, y, z);
103	  return j;
104	}
105	
106	/** hemisphere dome facing +Z with planar UVs (u,v = x,y mapped to 0..1) */
107	function domeGeometry(r: number, wSeg = 32, hSeg = 14): THREE.BufferGeometry {
108	  const g = new THREE.SphereGeometry(r, wSeg, hSeg, 0, Math.PI * 2, 0, Math.PI / 2);
109	  g.rotateX(Math.PI / 2); // +Y pole → +Z
110	  const p = g.attributes.position as THREE.BufferAttribute;
111	  const uv = g.attributes.uv as THREE.BufferAttribute;
112	  for (let i = 0; i < p.count; i++) uv.setXY(i, p.getX(i) / (2 * r) + 0.5, p.getY(i) / (2 * r) + 0.5);
113	  return g;
114	}
115	
116	/** a rectangular decal draped onto a sphere of radius `radius` around the origin, centred on `dir` */
117	function sphereDecal(dir: THREE.Vector3, w: number, h: number, radius: number, seg = 10): THREE.BufferGeometry {
118	  const g = new THREE.PlaneGeometry(w, h, seg, seg);
119	  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), dir.clone().normalize());
120	  const p = g.attributes.position as THREE.BufferAttribute;
121	  const v = new THREE.Vector3();
122	  for (let i = 0; i < p.count; i++) {
123	    v.set(p.getX(i), p.getY(i), radius).applyQuaternion(q).setLength(radius);
124	    p.setXYZ(i, v.x, v.y, v.z);
125	  }
126	  g.computeVertexNormals();
127	  return g;
128	}
129	
130	function std(o: THREE.MeshStandardMaterialParameters): THREE.MeshStandardMaterial {
131	  return new THREE.MeshStandardMaterial(o);
132	}
133	
134	function furData(o: {
135	  length: number;
136	  density: number;
137	  shells: number;
138	  root: string;
139	  tip: string;
140	  bald?: [number, number, number, number]; // dir (mesh-local) + dot threshold → no fur beyond it
141	  short?: [number, number, number, number, number, number]; // dir + t0,t1 + min factor
142	  gravity?: number;
143	}) {
144	  return { fur: { gravity: 0.35, ...o } };
145	}
146	
147	function lathe(points: [number, number][], segs: number, v0: number, v1: number, uRepeat = 1): THREE.LatheGeometry {
148	  const g = new THREE.LatheGeometry(points.map(([r, y]) => new THREE.Vector2(r, y)), segs);
149	  // re-map v to height so stripes are linear in height; u (around) optionally tiles the texture
150	  const p = g.attributes.position as THREE.BufferAttribute;
151	  const uv = g.attributes.uv as THREE.BufferAttribute;
152	  for (let i = 0; i < p.count; i++) uv.setXY(i, uv.getX(i) * uRepeat, (p.getY(i) - v0) / (v1 - v0));
153	  return g;
154	}
155	
156	function starShape(outer: number, inner: number): THREE.Shape {
157	  const s = new THREE.Shape();
158	  for (let i = 0; i < 10; i++) {
159	    const a = Math.PI / 2 + (i * Math.PI) / 5;
160	    const r = i % 2 === 0 ? outer : inner;
161	    const x = Math.cos(a) * r, y = Math.sin(a) * r;
162	    if (i === 0) s.moveTo(x, y); else s.lineTo(x, y);
163	  }
164	  s.closePath();
165	  return s;
166	}
167	
168	export function buildBenny(): BuiltModel {
169	  const D = BENNY_DIMS;
170	  const root = named(new THREE.Group(), 'benny_root');
171	  const body = joint('body');
172	  root.add(body);
173	
174	  // ---------------- body (fur) ----------------
175	  const hatUp = new THREE.Vector3(0, 1, 0).applyAxisAngle(new THREE.Vector3(1, 0, 0), D.hatTilt);
176	  const bodyMat = std({ color: C.pinkSkin, roughness: 0.92, metalness: 0 });
177	  const bodyGeo = new THREE.SphereGeometry(D.skin, 48, 36);
178	  {
179	    // pear-round plush ball. Normals come from finite differences of the deformation on the sphere
180	    // (position-only, so UV-seam / pole duplicates get identical normals and the shell fur stays closed)
181	    const p = bodyGeo.attributes.position as THREE.BufferAttribute;
182	    const n = bodyGeo.attributes.normal as THREE.BufferAttribute;
183	    const d = new THREE.Vector3(), t1 = new THREE.Vector3(), t2 = new THREE.Vector3();
184	    const a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3(), e = new THREE.Vector3();
185	    const s = new THREE.Vector3(), o = new THREE.Vector3();
186	    const eps = 1e-3;
187	    for (let i = 0; i < p.count; i++) {
188	      d.set(p.getX(i), p.getY(i), p.getZ(i)).normalize();
189	      t1.set(0, 1, 0).cross(d);
190	      if (t1.lengthSq() < 1e-6) t1.set(1, 0, 0).cross(d);
191	      t1.normalize();
192	      t2.crossVectors(d, t1).normalize();
193	      const at = (u: number, w: number, out: THREE.Vector3) =>
194	        deformBody(s.copy(d).addScaledVector(t1, u).addScaledVector(t2, w).setLength(D.skin), out);
195	      at(eps, 0, a); at(-eps, 0, b); at(0, eps, c); at(0, -eps, e);
196	      a.sub(b); c.sub(e);
197	      const nn = o.crossVectors(a, c).normalize();
198	      if (nn.dot(d) < 0) nn.negate();
199	      n.setXYZ(i, nn.x, nn.y, nn.z);
200	      deformBody(s.copy(d).multiplyScalar(D.skin), a);
201	      p.setXYZ(i, a.x, a.y, a.z);
202	    }
203	  }
204	  const bodyMesh = named(new THREE.Mesh(bodyGeo, bodyMat), 'fur_body');
205	  bodyMesh.userData = furData({
206	    length: D.fur,
207	    density: 64,
208	    shells: 20,
209	    root: C.pinkRoot,
210	    tip: C.pinkTip,
211	    // bald under the beanie: dot(normal, hatUp) > brimBottom/skin (+ a little overlap)
212	    // (wave 4: +0.07 → full-length fur tucks under the cuff edge; +0.03 left a bare pink collar under the cuff once
213	    // the ride lean shows the back of the ball)
214	    bald: [hatUp.x, hatUp.y, hatUp.z, (D.brimBottom + 0.07) / D.skin],
215	    short: [FACE_DIR.x, FACE_DIR.y, FACE_DIR.z, 0.74, 0.93, 0.26],
216	    gravity: 0.1,
217	  });
218	  body.add(bodyMesh);
219	
220	  // ---------------- face ----------------
221	  const eyes = joint('eyes');
222	  body.add(eyes);
223	  const eyeR = 0.178;
224	  const eyeGeo = domeGeometry(eyeR, 32, 12);
225	  eyeGeo.scale(1, 1.06, 0.55);
226	  const eyeMatHappy = std({ map: eyeTexture('happy'), roughness: 0.12, metalness: 0 });
227	  const eyeMatDizzy = std({ map: eyeTexture('dizzy'), roughness: 0.12, metalness: 0 });
228	  const lashMat = std({ color: '#241036', roughness: 0.5 });
229	  for (const side of [1, -1] as const) {
230	    // side +1 = Benny's left (+X), −1 = right (−X)
231	    const dir = new THREE.Vector3(0.34 * side, -0.005, 0.94).normalize();
232	    const e = joint(side > 0 ? 'eyeL' : 'eyeR');
233	    e.position.copy(dir).multiplyScalar(0.665);
234	    e.lookAt(dir.clone().multiplyScalar(5));
235	    eyes.add(e);
236	    const happy = named(new THREE.Mesh(eyeGeo, eyeMatHappy), side > 0 ? 'eyeL_happy' : 'eyeR_happy');
237	    const dizzy = named(new THREE.Mesh(eyeGeo, eyeMatDizzy), side > 0 ? 'eyeL_dizzy' : 'eyeR_dizzy');
238	    dizzy.visible = false;
239	    e.add(happy, dizzy);
240	    // two little upper lashes on the outer corner
241	    for (const [a, len] of [[0.5, 0.075], [0.85, 0.065]] as const) {
242	      // eye-local: +X of the eye frame points to Benny's left when looking from the front
243	      const ang = side > 0 ? a : Math.PI - a;
244	      const lash = new THREE.Mesh(new THREE.ConeGeometry(0.014, len, 6), lashMat);
245	      lash.position.set(Math.cos(ang) * eyeR * 1.0, Math.sin(ang) * eyeR * 1.05, 0.045);
246	      lash.rotation.z = ang - Math.PI / 2;
247	      lash.translateY(len * 0.45);
248	      lash.name = `lash_${side > 0 ? 'L' : 'R'}_${a}`;
249	      e.add(lash);
250	    }
251	  }
252	  // blush
253	  const blushMat = std({ map: blushTexture(), transparent: true, depthWrite: false, roughness: 0.8 });
254	  for (const side of [1, -1]) {
255	    const m = named(new THREE.Mesh(sphereDecal(new THREE.Vector3(0.6 * side, -0.24, 0.78), 0.3, 0.19, 0.775), blushMat), side > 0 ? 'blushL' : 'blushR');
256	    m.renderOrder = 2;
257	    body.add(m);
258	  }
259	  // nose
260	  const nose = named(new THREE.Mesh(new THREE.SphereGeometry(0.03, 12, 8), std({ color: '#7d2550', roughness: 0.35 })), 'nose');
261	  nose.position.copy(new THREE.Vector3(0, -0.13, 1).normalize().multiplyScalar(0.738));
262	  nose.scale.set(1.3, 0.9, 0.8);
263	  body.add(nose);
264	  // mouth decals (alpha-tested)
265	  const mouth = joint('mouth');
266	  body.add(mouth);
267	  const mouthDir = new THREE.Vector3(0, -0.34, 0.94);
268	  for (const kind of ['happy', 'dizzy', 'peek'] as const) {
269	    const w = kind === 'dizzy' ? 0.19 : 0.29;
270	    const m = named(
271	      new THREE.Mesh(
272	        sphereDecal(mouthDir, w, w, 0.752, 8),
273	        std({ map: mouthTexture(kind), alphaTest: 0.5, roughness: 0.4, side: THREE.DoubleSide }),
274	      ),
275	      `mouth_${kind}`,
276	    );
277	    m.visible = kind === 'happy';
278	    mouth.add(m);
279	  }
280	
281	  // ---------------- arms ----------------
282	  const armMat = std({ color: C.pinkSkin, roughness: 0.92 });
283	  const palmTex = soleTexture('hand');
284	  for (const side of [1, -1] as const) {
285	    // round paw nubs stick out left/right just under the cuff (rear ref 05: ≈ 53 px round balls, centres ≈ 35 px
286	    // below the cuff's side corners and ≈ 0.92 cuff-half-widths out). Wave 4: a near-sphere with short dense fur
287	    // (was a 1.25× elongated ellipsoid with long drooping fur that read as fuzzy wings from behind).
288	    const a = joint(side > 0 ? 'armL' : 'armR', 0.71 * side, -0.06, 0.0);
289	    body.add(a);
290	    const phi = 1.3 * side;
291	    const dir = new THREE.Vector3(Math.sin(phi), -Math.cos(phi), 0);
292	    const g = new THREE.SphereGeometry(0.13, 20, 14);
293	    g.scale(1, 1.06, 1);
294	    const arm = named(new THREE.Mesh(g, armMat), side > 0 ? 'fur_armL' : 'fur_armR');
295	    arm.position.copy(dir).multiplyScalar(0.18);
296	    arm.rotation.z = phi;
297	    arm.userData = furData({ length: 0.055, density: 96, shells: 12, root: C.pinkRoot, tip: C.pinkTip, gravity: 0.04 });
298	    a.add(arm);
299	    const palm = named(
300	      new THREE.Mesh(new THREE.CircleGeometry(0.07, 24), std({ map: palmTex, roughness: 0.6 })),
301	      side > 0 ? 'palmL' : 'palmR',
302	    );
303	    palm.position.copy(dir).multiplyScalar(0.24).add(new THREE.Vector3(0, -0.01, 0.1));
304	    palm.rotation.x = -0.25;
305	    a.add(palm);
306	  }
307	
308	  // ---------------- feet ----------------
309	  const footTex = soleTexture('foot');
310	  for (const side of [1, -1] as const) {
311	    const f = joint(side > 0 ? 'footL' : 'footR', 0.31 * side, -0.65, 0.27);
312	    body.add(f);
313	    const g = new THREE.SphereGeometry(0.2, 22, 16);
314	    g.scale(1, 0.82, 1.12);
315	    const foot = named(new THREE.Mesh(g, armMat), side > 0 ? 'fur_footL' : 'fur_footR');
316	    foot.position.set(0, -0.03, 0.06);
317	    foot.userData = furData({
318	      length: 0.06, density: 70, shells: 8, root: C.pinkRoot, tip: C.pinkTip, gravity: 0.1,
319	      bald: [0, -0.55, 0.83, 0.55],
320	    });
321	    f.add(foot);
322	    const sole = named(new THREE.Mesh(new THREE.CircleGeometry(0.165, 28), std({ map: footTex, roughness: 0.55 })), side > 0 ? 'soleL' : 'soleR');
323	    sole.scale.set(1, 1.08, 1);
324	    sole.position.set(0, -0.085, 0.235);
325	    // faces forward and a little down (lookAt in foot-local space: sole has no parent yet)
326	    sole.lookAt(sole.position.clone().add(new THREE.Vector3(0, -0.55, 0.83)));
327	    f.add(sole);
328	  }
329	
330	  // ---------------- knitted beanie ----------------
331	  const hat = joint('hat');
332	  hat.rotation.x = D.hatTilt;
333	  body.add(hat);
334	  const yb = D.brimBottom;
335	  const yt = yb + D.cuffH; // cuff top
336	  const bk = D.brimR / 0.778; // profile scale (profiles were authored for a 0.778 brim)
337	  const brimTex = ribbedBrimTextures();
338	  // base-colour factors (wave 5): the tone-mapped scene light lifted the knit to lavender (live 05 cuff median #B248FF
339	  // L167, ref 05 #6B0DEB L117; refs 03/07 also paint a deep-violet cuff). In-game A/B (?bennyTint): cuff ×#7868a0 →
340	  // #620BEE L118; the crown gets a milder warm factor so the white stripes stay cream-white in every scene
341	  const brimMat = std({ color: '#7868a0', map: brimTex.map, normalMap: brimTex.normalMap, normalScale: new THREE.Vector2(1.25, 1.25), roughness: 0.86 });
342	  // inner lip hugs the skin at the brim height (sphere radius there ≈ 0.68)
343	  const lip = Math.sqrt(D.skin * D.skin - yb * yb) + 0.012;
344	  // chunky rolled cuff: rounded bottom and top edges, slight belly in the middle
345	  const brim = named(
346	    new THREE.Mesh(
347	      lathe(
348	        [
349	          [lip, yb + 0.01],
350	          [0.725 * bk, yb - 0.008],
351	          [0.758 * bk, yb + 0.02],
352	          [0.776 * bk, yb + 0.07],
353	          [0.781 * bk, yb + 0.15],
354	          [0.776 * bk, yt - 0.075],
355	          [0.758 * bk, yt - 0.025],
356	          [0.725 * bk, yt - 0.003],
357	          [0.68 * bk, yt],
358	        ],
359	        72,
360	        yb - 0.01,
361	        yt + 0.005,
362	      ),
363	      brimMat,
364	    ),
365	    'hat_brim',
366	  );
367	  // the brim texture's "v" should run across the band (ribs vertical): lathe u = around ✓
368	  hat.add(brim);
369	  const crownTex = knitCrownTextures();
370	  const crownMat = std({ color: '#eae6d6', map: crownTex.map, normalMap: crownTex.normalMap, normalScale: new THREE.Vector2(1.3, 1.3), roughness: 0.9 });
371	  // crown dome: starts inside the cuff and is narrower than it (the chunky cuff flares out, refs 04–10), with
372	  // an elliptic profile r = R0·√(1 − (y/H)²) that tapers to the pom-pom (which covers the apex).
373	  // v = height → horizontal knit stripes.
374	  const crownY0 = yt - 0.045;
375	  const R0 = 0.705 * bk;
376	  const crownProfile: [number, number][] = [];
377	  for (const t of [0, 0.08, 0.16, 0.25, 0.34, 0.43, 0.52, 0.6, 0.68, 0.75, 0.81, 0.86, 0.9, 0.935, 0.96, 0.98, 0.993, 1]) {
378	    // wave 4: × (1 − 0.18 t) tapers the shoulders (ref 05 rear: dome half-width ≈ 0.85 / 0.77 / 0.66 / 0.54 of the
379	    // cuff's at 0 / 0.11 / 0.27 / 0.38 above the cuff top: a rounded beehive, not a flat-topped mushroom)
380	    crownProfile.push([R0 * Math.sqrt(Math.max(0, 1 - t * t)) * (1 - 0.18 * t), crownY0 + t * D.crownH]);
381	  }
382	  const crown = named(
383	    new THREE.Mesh(lathe(crownProfile, 72, crownY0, crownY0 + D.crownH, CROWN_REPEAT), crownMat),
384	    'hat_crown',
385	  );
386	  hat.add(crown);
387	  // puffy gold star badge sewn on the lower white stripe just above the cuff, rear-RIGHT (−X): image-right of
388	  // centre in the rear gameplay views (ref 05: centre at ≈ +0.68 of the cuff half-width, ≈ 0.11 × the cuff width
389	  // above the cuff's top edge, ≈ 0.27 × the cuff width across, its lower points overlapping the cuff). Its face
390	  // is turned toward the back (normal 160° from the front) and leans back against the sloping crown (tilted 25°
391	  // up), so the rear ride cameras (10–25° above Benny) see it face-on, never edge-on.
392	  const starGeo = new THREE.ExtrudeGeometry(starShape(0.165, 0.083), {
393	    depth: 0.02,
394	    bevelEnabled: true,
395	    bevelThickness: 0.045,
396	    bevelSize: 0.032,
397	    bevelSegments: 4,
398	  });
399	  starGeo.center();
400	  const star = named(
401	    new THREE.Mesh(starGeo, std({ color: C.gold, metalness: 0.12, roughness: 0.3, emissive: '#ffb800', emissiveIntensity: 0.22 })),
402	    'hat_star',
403	  );
404	  const sa = THREE.MathUtils.degToRad(D.starAng);
405	  // wave 4: centred on the cuff's top edge (ref 05: ≈ 40 % of the star on the cuff, the rest on the white band);
406	  // leans back only 12° because the runtime's ride lean (≈ 13°) tips it the rest of the way toward the chase camera
407	  const starPos = new THREE.Vector3(-Math.sin(sa) * D.starR, yt + D.starY, Math.cos(sa) * D.starR);
408	  const na = THREE.MathUtils.degToRad(160), tilt = THREE.MathUtils.degToRad(12);
409	  const starN = new THREE.Vector3(-Math.sin(na) * Math.cos(tilt), Math.sin(tilt), Math.cos(na) * Math.cos(tilt));
410	  star.position.copy(starPos);
411	  star.lookAt(starPos.clone().add(starN));
412	  star.rotateZ(-0.14);
413	  hat.add(star);
414	  // big fluffy-round pom-pom sitting ON the crown apex (≈ 0.5 × the cuff width wide and ≈ 0.46 × tall above the
415	  // crown in ref 05; wave 3 raised it out of the crown and moved it back over the apex against the forward tilt)
416	  // wave 4: core centre 0.12 above the dome apex → the lower third of the pom nests in the dome (ref 05: the top purple
417	  // band shows around its base), slightly to the back so the ride lean keeps it centred over the dome
418	  const pom = joint('pom', 0, crownY0 + D.crownH + 0.12, -0.05);
419	  hat.add(pom);
420	  const pomMesh = named(new THREE.Mesh(new THREE.SphereGeometry(D.pomR, 32, 24), std({ color: C.pomRoot, roughness: 0.95 })), 'fur_pom');
421	  // short, dense strands with little droop → a round plush ball rather than a spiky urchin
422	  pomMesh.userData = furData({ length: 0.12, density: 88, shells: 16, root: C.pomRoot, tip: C.pomTip, gravity: 0.05 });
423	  pom.add(pomMesh);
424	
425	  const animations = buildClips();
426	  return { scene: root, animations };
427	}
428	
429	// ------------------------------------------------------------------ clips
430	type E3 = [number, number, number];
431	const q = (e: E3) => new THREE.Quaternion().setFromEuler(new THREE.Euler(e[0], e[1], e[2]));
432	
433	function qTrack(node: string, times: number[], eulers: E3[]): THREE.QuaternionKeyframeTrack {
434	  const vals: number[] = [];
435	  eulers.forEach((e) => vals.push(...q(e).toArray()));
436	  return new THREE.QuaternionKeyframeTrack(`${node}.quaternion`, times, vals);
437	}
438	function vTrack(node: string, prop: 'position' | 'scale', times: number[], vecs: E3[]): THREE.VectorKeyframeTrack {
439	  return new THREE.VectorKeyframeTrack(`${node}.${prop}`, times, vecs.flat());
440	}
441	function loop(n: number, dur: number): number[] {
442	  return Array.from({ length: n + 1 }, (_, i) => (i / n) * dur);
443	}
444	
445	const ARM_L: E3 = [0.7, -0.08, 0.03];
446	const ARM_R: E3 = [-0.7, -0.08, 0.03];
447	const FOOT_L: E3 = [0.31, -0.65, 0.27];
448	const FOOT_R: E3 = [-0.31, -0.65, 0.27];
449	
450	function buildClips(): THREE.AnimationClip[] {
451	  const N = 12;
452	  const tau = Math.PI * 2;
453	  // idle
454	  const ti = loop(N, 2.4);
455	  const idle = new THREE.AnimationClip('idle', 2.4, [
456	    vTrack('body', 'position', ti, ti.map((t) => [0, Math.sin((t / 2.4) * tau) * 0.015, 0])),
457	    qTrack('armL', ti, ti.map((t) => [0, 0, Math.sin((t / 2.4) * tau) * 0.08])),
458	    qTrack('armR', ti, ti.map((t) => [0, 0, -Math.sin((t / 2.4) * tau) * 0.08])),
459	    qTrack('footL', ti, ti.map(() => [0, 0, 0])),
460	    qTrack('footR', ti, ti.map(() => [0, 0, 0])),
461	    qTrack('body', ti, ti.map(() => [0, 0, 0])),
462	  ]);
463	  // swim — paws paddle, feet kick, body bobs (0.6 s loop)
464	  const D = 0.6;
465	  const ts = loop(N, D);
466	  const ph = (t: number) => (t / D) * tau;
467	  const swim = new THREE.AnimationClip('swim', D, [
468	    vTrack('body', 'position', ts, ts.map((t) => [0, Math.abs(Math.sin(ph(t))) * 0.04 - 0.01, 0])),
469	    qTrack('body', ts, ts.map((t) => [Math.sin(ph(t) * 2) * 0.03, 0, Math.sin(ph(t)) * 0.05])),
470	    qTrack('armL', ts, ts.map((t) => [Math.sin(ph(t)) * 0.75, 0, 0.25 + Math.cos(ph(t)) * 0.2])),
471	    qTrack('armR', ts, ts.map((t) => [Math.sin(ph(t) + Math.PI) * 0.75, 0, -0.25 - Math.cos(ph(t) + Math.PI) * 0.2])),
472	    qTrack('footL', ts, ts.map((t) => [Math.sin(ph(t) + Math.PI) * 0.5, 0, 0])),
473	    qTrack('footR', ts, ts.map((t) => [Math.sin(ph(t)) * 0.5, 0, 0])),
474	  ]);
475	  // tumble — paws flail up, feet kick fast (caller spins the root)
476	  const T = 1.0;
477	  const tt = loop(N, T);
478	  const pt = (t: number) => (t / T) * tau;
479	  const tumble = new THREE.AnimationClip('tumble', T, [
480	    vTrack('body', 'position', tt, tt.map(() => [0, 0, 0])),
481	    qTrack('body', tt, tt.map((t) => [0, 0, Math.sin(pt(t)) * 0.1])),
482	    qTrack('armL', tt, tt.map((t) => [Math.sin(pt(t) * 2) * 0.4, 0, 1.25 + Math.sin(pt(t) * 3) * 0.3])),
483	    qTrack('armR', tt, tt.map((t) => [Math.cos(pt(t) * 2) * 0.4, 0, -1.25 - Math.cos(pt(t) * 3) * 0.3])),
484	    qTrack('footL', tt, tt.map((t) => [Math.sin(pt(t) * 3) * 0.6, 0, 0.2])),
485	    qTrack('footR', tt, tt.map((t) => [Math.sin(pt(t) * 3 + Math.PI) * 0.6, 0, -0.2])),
486	  ]);
487	  // peek — paws hold the towel edge, gentle sway (scene 01)
488	  const P = 2.0;
489	  const tp = loop(N, P);
490	  const pp = (t: number) => (t / P) * tau;
491	  const peek = new THREE.AnimationClip('peek', P, [
492	    vTrack('body', 'position', tp, tp.map((t) => [0, 0.03 + Math.sin(pp(t)) * 0.02, 0])),
493	    qTrack('body', tp, tp.map((t) => [0.04, 0, Math.sin(pp(t)) * 0.07])),
494	    qTrack('armL', tp, tp.map((t) => [-1.15 + Math.sin(pp(t) * 2) * 0.05, 0, 0.35])),
495	    qTrack('armR', tp, tp.map((t) => [-1.15 + Math.cos(pp(t) * 2) * 0.05, 0, -0.35])),
496	    qTrack('footL', tp, tp.map(() => [0, 0, 0])),
497	    qTrack('footR', tp, tp.map(() => [0, 0, 0])),
498	  ]);
499	  void ARM_L; void ARM_R; void FOOT_L; void FOOT_R;
500	  return [idle, swim, tumble, peek];
501	}
