1	/**
2	 * Real-time shell-texturing fur for Benny (mobile-safe, one draw call per furry part).
3	 *
4	 * Each fur_* mesh becomes an InstancedMesh with `shells` instances; gl_InstanceID selects the
5	 * shell layer, which is pushed out along the normal (plus a little gravity droop). A hashed 3-D
6	 * strand grid decides per-fragment whether a strand still exists at that height (tapering strands),
7	 * so the fur keeps a fluffy silhouette from every angle. Built on MeshStandardMaterial via
8	 * onBeforeCompile so scene lighting, IBL and fog all still apply.
9	 */
10	import * as THREE from 'three';
11	
12	export interface FurParams {
13	  length: number;
14	  density: number;
15	  shells: number;
16	  root: string;
17	  tip: string;
18	  gravity?: number;
19	  bald?: [number, number, number, number];
20	  short?: [number, number, number, number, number, number];
21	}
22	
23	export interface FurHandle {
24	  mesh: THREE.InstancedMesh;
25	  material: THREE.MeshStandardMaterial;
26	  uniforms: { uTime: { value: number }; uWind: { value: THREE.Vector3 }; uMaskCol: { value: THREE.Color } };
27	}
28	
29	export function makeFur(src: THREE.Mesh, p: FurParams): FurHandle {
30	  const shells = Math.max(2, Math.round(p.shells));
31	  const uniforms = {
32	    uFurLen: { value: p.length },
33	    uDensity: { value: p.density },
34	    uRoot: { value: new THREE.Color(p.root) },
35	    uTip: { value: new THREE.Color(p.tip) },
36	    uGravity: { value: p.gravity ?? 0.3 },
37	    uBald: { value: new THREE.Vector4(...(p.bald ?? [0, 1, 0, 2])) },
38	    uShortDir: { value: new THREE.Vector3(...((p.short?.slice(0, 3) as [number, number, number]) ?? [0, 0, 1])) },
39	    uShort: { value: new THREE.Vector3(p.short?.[3] ?? 2, p.short?.[4] ?? 3, p.short?.[5] ?? 1) },
40	    uTime: { value: 0 },
41	    uWind: { value: new THREE.Vector3() },
42	    /** QA segmentation colour (only compiled in when material.defines.BENNY_MASK is set, see runtime.ts) */
43	    uMaskCol: { value: new THREE.Color(1, 0, 0) },
44	  };
45	  const material = new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 0.9, metalness: 0 });
46	  material.onBeforeCompile = (shader) => {
47	    Object.assign(shader.uniforms, uniforms);
48	    shader.vertexShader = shader.vertexShader
49	      .replace(
50	        '#include <common>',
51	        `#include <common>
52	        uniform float uFurLen; uniform float uGravity; uniform vec4 uBald;
53	        uniform vec3 uShortDir; uniform vec3 uShort; uniform float uTime; uniform vec3 uWind;
54	        varying float vLayer; varying vec3 vBase; varying float vLenMask;`,
55	      )
56	      .replace(
57	        '#include <begin_vertex>',
58	        `#include <begin_vertex>
59	        vLayer = float(gl_InstanceID) / float(${shells - 1});
60	        vec3 nrm = normalize(objectNormal);
61	        float bald = 1.0 - smoothstep(uBald.w - 0.04, uBald.w + 0.01, dot(nrm, normalize(uBald.xyz)));
62	        float sh = mix(1.0, uShort.z, smoothstep(uShort.x, uShort.y, dot(nrm, normalize(uShortDir))));
63	        vLenMask = bald * sh;
64	        vBase = position;
65	        float h = uFurLen * vLayer * vLenMask;
66	        transformed += nrm * h;
67	        // gravity droop + gentle wind sway grows with layer height
68	        vec3 g = vec3(0.0, -1.0, 0.0) * uGravity + uWind;
69	        g += vec3(sin(uTime * 3.0 + position.y * 9.0), 0.0, cos(uTime * 2.3 + position.x * 7.0)) * 0.06;
70	        transformed += g * uFurLen * vLayer * vLayer * vLenMask;`,
71	      );
72	    shader.fragmentShader = shader.fragmentShader
73	      .replace(
74	        '#include <common>',
75	        `#include <common>
76	        uniform float uDensity; uniform vec3 uRoot; uniform vec3 uTip;
77	        varying float vLayer; varying vec3 vBase; varying float vLenMask;
78	        float fhash(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
79	        vec3 fhash3(vec3 p) { return vec3(fhash(p), fhash(p + 17.31), fhash(p + 41.7)); }`,
80	      )
81	      .replace(
82	        '#include <color_fragment>',
83	        `#include <color_fragment>
84	        {
85	          vec3 q = vBase * uDensity;
86	          // clumping: strands lean toward low-frequency tuft centres as they rise → plush tufts
87	          vec3 qc = q * 0.2;
88	          vec3 cc = (floor(qc) + 0.5 + (fhash3(floor(qc)) - 0.5) * 0.7) / 0.2;
89	          q = mix(q, cc, vLayer * 0.42);
90	          vec3 cell = floor(q);
91	          float best = 10.0; float hgt = 0.0;
92	          // nearest strand among this + neighbouring cells (gives round, jittered strands)
93	          for (int k = 0; k < 8; k++) {
94	            vec3 o = vec3(float(k & 1), float((k >> 1) & 1), float((k >> 2) & 1));
95	            vec3 c = floor(q - 0.5) + o;
96	            vec3 jp = c + 0.5 + (fhash3(c) - 0.5) * 0.8;
97	            float d = length(q - jp);
98	            if (d < best) { best = d; hgt = fhash(c * 1.7 + 3.1); }
99	          }
100	          float layer = vLayer;
101	          if (layer > 0.001) {
102	            if (vLenMask < 0.05) discard;
103	            float strandH = 0.55 + 0.45 * hgt;
104	            float radius = 0.78 * (1.0 - 0.85 * layer / strandH);
105	            if (layer > strandH || best > radius) discard;
106	          }
107	          float ao = mix(0.55, 1.0, smoothstep(0.0, 0.9, layer));
108	          diffuseColor.rgb = mix(uRoot, uTip, smoothstep(0.0, 1.0, layer)) * ao * (0.92 + 0.16 * hgt);
109	        }`,
110	      )
111	      .replace(
112	        '#include <emissivemap_fragment>',
113	        `#include <emissivemap_fragment>
114	        totalEmissiveRadiance += diffuseColor.rgb * 0.10 * vLayer;`,
115	      )
116	      .replace(
117	        '#include <dithering_fragment>',
118	        `#include <dithering_fragment>
119	        #ifdef BENNY_MASK
120	        gl_FragColor = vec4(uMaskCol, 1.0);
121	        #endif`,
122	      );
123	    shader.fragmentShader = shader.fragmentShader.replace('uniform vec3 uTip;', 'uniform vec3 uTip; uniform vec3 uMaskCol;');
124	  };
125	  material.customProgramCacheKey = () => `benny-fur-${shells}${material.defines?.BENNY_MASK !== undefined ? '-mask' : ''}`;
126	
127	  const mesh = new THREE.InstancedMesh(src.geometry, material, shells);
128	  const I = new THREE.Matrix4();
129	  for (let i = 0; i < shells; i++) mesh.setMatrixAt(i, I);
130	  mesh.instanceMatrix.needsUpdate = true;
131	  mesh.name = src.name;
132	  mesh.position.copy(src.position);
133	  mesh.quaternion.copy(src.quaternion);
134	  mesh.scale.copy(src.scale);
135	  mesh.frustumCulled = false;
136	  return { mesh, material, uniforms };
137	}
