1	/**
2	 * Runtime Benny: loads the canonical assets/models/benny.glb, upgrades fur_* meshes to shell fur,
3	 * and drives expressions + procedural secondary motion on top of the GLB clips.
4	 */
5	import * as THREE from 'three';
6	import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
7	import type { BennyRuntime } from '../types';
8	import { makeFur, type FurHandle, type FurParams } from './fur';
9	
10	const BENNY_URL = new URL('../../../assets/models/benny.glb', import.meta.url).href;
11	
12	let cached: Promise<THREE.Group> | null = null;
13	
14	function loadScene(): Promise<THREE.Group> {
15	  if (!cached) cached = new GLTFLoader().loadAsync(BENNY_URL).then((g) => {
16	    const s = g.scene as THREE.Group;
17	    s.userData.animations = g.animations;
18	    return s;
19	  });
20	  return cached;
21	}
22	
23	/** fur tier: explicit option, else `?quality=low|high`, else low on Android/iOS (same rule as the water) */
24	function defaultFurQuality(): 'high' | 'low' {
25	  if (typeof location === 'undefined') return 'high';
26	  const qp = new URLSearchParams(location.search).get('quality');
27	  const mobile = typeof navigator !== 'undefined' && /Android|iPhone|iPad/i.test(navigator.userAgent);
28	  return qp === 'low' || (qp !== 'high' && mobile) ? 'low' : 'high';
29	}
30	
31	export async function loadBenny(opts: { furQuality?: 'high' | 'low' } = {}): Promise<BennyRuntime> {
32	  const src = await loadScene();
33	  const clips: THREE.AnimationClip[] = src.userData.animations ?? [];
34	  return createBennyRuntime(src.clone(true), clips, { furQuality: opts.furQuality ?? defaultFurQuality() });
35	}
36	
37	/**
38	 * Ride height. The game places the root at water surface + radius·0.55 (≈ 0.44), which buried the lower
39	 * third of the plush ball in the opaque stream. While riding (swim ≥ 0.5, not tumbling) the model is
40	 * lifted inside the root so he sits ON the water like refs 04–10: only the bottom of the fur and the
41	 * kicking feet are under the surface. Cinematics (01 peek, 02 tumble, 11 hide) keep the root as placed.
42	 * Wave 4: 0.30 → 0.22 together with the ride lean, which shows more of his back: keeps the pom-pom top at the
43	 * ref-05 height (≈ 765 px, under the first coin) and the cuff bottom where the ref has it.
44	 * Wave 5: 0.22 → 0.12. Measured in the live 05 capture with the re-exported GLB (flat-ID mask): 0.22 put the pom top at
45	 * 748 and the bottom at 1178; 0.12 gives bbox x 231–612 / y 766–1188, cuff bottom 1029, hat incl. pom 62 % / body 38 %
46	 * (ref 05: x 230–612 / y 767–≈1185, cuff bottom ≈ 1028).
47	 */
48	export const BENNY_RIDE_LIFT = 0.12;
49	/** QA A/B hook: `?bennyLift=<units>` overrides the ride lift (e.g. 0 = the game's raw placement) */
50	function rideLift(): number {
51	  if (typeof location === 'undefined') return BENNY_RIDE_LIFT;
52	  const v = parseFloat(new URLSearchParams(location.search).get('bennyLift') ?? '');
53	  return Number.isFinite(v) ? THREE.MathUtils.clamp(v, 0, 0.6) : BENNY_RIDE_LIFT;
54	}
55	
56	/**
57	 * Ride lean (rad, about his X axis, + = top forward). While riding he leans into the current like a swimmer, so the
58	 * rear chase cameras (04–10: ≈ 25° above him) see the beanie and the plush back the way the references paint
59	 * them (≈ 10–12° above: knit stripes and cuff read as level bands, the dome as a tall cap, not a flat disc).
60	 * Eased in with the ride lift; cinematics (01 peek, 02 tumble, 11 hide) keep him upright. The game can scale it
61	 * per shot with `benny.root.userData.ridePitch` (0…1, default 1), e.g. 0 in the 03 twirl where he faces the camera.
62	 */
63	export const BENNY_RIDE_PITCH = 0.22;
64	function ridePitch(): number {
65	  if (typeof location === 'undefined') return BENNY_RIDE_PITCH;
66	  const v = parseFloat(new URLSearchParams(location.search).get('bennyPitch') ?? '');
67	  return Number.isFinite(v) ? THREE.MathUtils.clamp(THREE.MathUtils.degToRad(v), -0.5, 0.5) : BENNY_RIDE_PITCH;
68	}
69	
70	/** Build the runtime around an already-loaded (or freshly built) Benny scene graph. */
71	export function createBennyRuntime(
72	  scene: THREE.Object3D,
73	  clips: THREE.AnimationClip[],
74	  opts: { furQuality?: 'high' | 'low' } = {},
75	): BennyRuntime {
76	  const root = new THREE.Group();
77	  root.name = 'Benny';
78	  root.add(scene);
79	
80	  // ---- fur upgrade ----
81	  const furs: FurHandle[] = [];
82	  const toReplace: THREE.Mesh[] = [];
83	  scene.traverse((o) => {
84	    const m = o as THREE.Mesh;
85	    if (m.isMesh && m.name.startsWith('fur_') && m.userData?.fur) toReplace.push(m);
86	  });
87	  for (const m of toReplace) {
88	    const p = { ...(m.userData.fur as FurParams) };
89	    if (opts.furQuality === 'low') p.shells = Math.max(6, Math.round(p.shells * 0.6));
90	    const h = makeFur(m, p);
91	    m.parent!.add(h.mesh);
92	    m.parent!.remove(m);
93	    furs.push(h);
94	  }
95	
96	  // QA colour A/B: `?bennyTint=hat_brim:7868a0,hat_crown:e4d4e4` sets the base-colour factor of meshes whose name
97	  // starts with the given prefix (the GLB's own factors are the default; materials are shared by every clone)
98	  if (typeof location !== 'undefined') {
99	    const tint = new URLSearchParams(location.search).get('bennyTint');
100	    for (const kv of tint ? tint.split(',') : []) {
101	      const [prefix, hex] = kv.split(':');
102	      if (!prefix || !/^[0-9a-f]{6}$/i.test(hex ?? '')) continue;
103	      scene.traverse((o) => {
104	        const m = o as THREE.Mesh;
105	        if (m.isMesh && m.name.startsWith(prefix)) (m.material as THREE.MeshStandardMaterial).color?.set(`#${hex}`);
106	      });
107	    }
108	  }
109	
110	  const get = (n: string) => scene.getObjectByName(n)!;
111	  const body = get('body');
112	  const pom = get('pom');
113	  const eyeL = get('eyeL');
114	  const eyeR = get('eyeR');
115	  const eyesGroup = get('eyes');
116	  const pomRest = pom.quaternion.clone();
117	
118	  // ---- animation mixer: idle ↔ swim blend, tumble / peek on demand ----
119	  const mixer = new THREE.AnimationMixer(scene);
120	  const act = (name: string) => {
121	    const c = clips.find((k) => k.name === name);
122	    return c ? mixer.clipAction(c) : null;
123	  };
124	  const aIdle = act('idle'), aSwim = act('swim'), aTumble = act('tumble'), aPeek = act('peek');
125	  for (const a of [aIdle, aSwim, aTumble, aPeek]) a?.play();
126	  const setW = (a: THREE.AnimationAction | null, w: number) => a && a.setEffectiveWeight(w);
127	
128	  let expression: 'happy' | 'dizzy' | 'peek' = 'happy';
129	  const setExpression = (e: 'happy' | 'dizzy' | 'peek') => {
130	    expression = e;
131	    for (const s of ['L', 'R']) {
132	      const h = scene.getObjectByName(`eye${s}_happy`);
133	      const d = scene.getObjectByName(`eye${s}_dizzy`);
134	      if (h) h.visible = e !== 'dizzy';
135	      if (d) d.visible = e === 'dizzy';
136	    }
137	    for (const k of ['happy', 'dizzy', 'peek']) {
138	      const m = scene.getObjectByName(`mouth_${k}`);
139	      if (m) m.visible = k === e;
140	    }
141	    eyesGroup.scale.setScalar(e === 'peek' ? 1.06 : 1);
142	  };
143	  setExpression('happy');
144	
145	  // ---- secondary motion state ----
146	  let pomAngX = 0, pomVelX = 0, pomAngZ = 0, pomVelZ = 0;
147	  let lastY = 0, lastVy = 0;
148	  let blinkT = 1.7;
149	  let lean = 0;
150	  let lift = 0;
151	  const liftMax = rideLift();
152	  let pitch = 0;
153	  const pitchMax = ridePitch();
154	  const tmp = new THREE.Vector3();
155	  const qLean = new THREE.Quaternion();
156	  const qPom = new THREE.Quaternion();
157	  const eAxis = new THREE.Euler();
158	
159	  const update: BennyRuntime['update'] = (dt, st) => {
160	    dt = Math.min(dt, 1 / 20);
161	    // clip weights
162	    const tumble = !!st.tumble;
163	    const swim = tumble ? 0 : THREE.MathUtils.clamp(st.swim, 0, 1);
164	    const peek = expression === 'peek' && !tumble ? 1 : 0;
165	    setW(aTumble, tumble ? 1 : 0);
166	    setW(aPeek, peek);
167	    setW(aSwim, peek ? 0 : swim);
168	    setW(aIdle, tumble || peek ? 0 : 1 - swim);
169	    if (aSwim) aSwim.timeScale = 0.8 + Math.min(1.2, st.speed / 14);
170	    mixer.update(dt);
171	
172	    // ride height (see BENNY_RIDE_LIFT): eased so mode switches never pop
173	    const liftTarget = tumble || peek ? 0 : liftMax * THREE.MathUtils.smoothstep(swim, 0.5, 0.9);
174	    lift += (liftTarget - lift) * (1 - Math.exp(-dt * 7));
175	    scene.position.y = lift;
176	    // ride lean into the current (see BENNY_RIDE_PITCH), on the same ease as the lift
177	    const pitchScale = typeof root.userData.ridePitch === 'number' ? THREE.MathUtils.clamp(root.userData.ridePitch, 0, 1) : 1;
178	    const pitchTarget = tumble || peek ? 0 : pitchMax * pitchScale * THREE.MathUtils.smoothstep(swim, 0.5, 0.9);
179	    pitch += (pitchTarget - pitch) * (1 - Math.exp(-dt * 7));
180	
181	    // steering lean (roll) + slight yaw into the turn
182	    lean += (THREE.MathUtils.clamp(st.steer, -1, 1) * 0.28 - lean) * Math.min(1, dt * 6);
183	    qLean.setFromEuler(eAxis.set(pitch, -lean * 0.6, -lean));
184	    body.quaternion.multiply(qLean);
185	
186	    // pom-pom spring: driven by vertical acceleration, steering and speed jitter
187	    root.getWorldPosition(tmp);
188	    const vy = (tmp.y - lastY) / Math.max(dt, 1e-3);
189	    const ay = THREE.MathUtils.clamp((vy - lastVy) / Math.max(dt, 1e-3), -80, 80);
190	    lastY = tmp.y; lastVy = vy;
191	    const k = 120, c = 9;
192	    const targetX = -ay * 0.004 + Math.sin(st.time * 11) * 0.03 * Math.min(1, st.speed / 12);
193	    const targetZ = lean * 0.9;
194	    pomVelX += (k * (targetX - pomAngX) - c * pomVelX) * dt;
195	    pomAngX += pomVelX * dt;
196	    pomVelZ += (k * (targetZ - pomAngZ) - c * pomVelZ) * dt;
197	    pomAngZ += pomVelZ * dt;
198	    qPom.setFromEuler(eAxis.set(THREE.MathUtils.clamp(pomAngX, -0.6, 0.6), 0, THREE.MathUtils.clamp(pomAngZ, -0.6, 0.6)));
199	    pom.quaternion.copy(pomRest).multiply(qPom);
200	
201	    // blink (cartoon squash of the eyes); no blinking while dizzy
202	    blinkT -= dt;
203	    let blink = 1;
204	    if (expression !== 'dizzy') {
205	      if (blinkT < 0.14) blink = Math.abs(blinkT - 0.07) / 0.07;
206	      if (blinkT <= 0) blinkT = 2.2 + Math.random() * 2.6;
207	    }
208	    eyeL.scale.y = eyeR.scale.y = Math.max(0.08, blink);
209	
210	    for (const f of furs) {
211	      f.uniforms.uTime.value = st.time;
212	      f.uniforms.uWind.value.set(0, 0, -Math.min(0.6, st.speed / 25));
213	    }
214	  };
215	
216	  // ---- QA segmentation mask (`?bennyMask`, or window.__bennyQA.mask(true) in ?qa pages) ----
217	  if (typeof location !== 'undefined') {
218	    const qs = new URLSearchParams(location.search);
219	    const qa = { mask: (on: boolean) => setMask(scene, furs, on), info: () => qaInfo(root, body) };
220	    if (qs.has('qa') || qs.has('bennyMask')) (window as unknown as { __bennyQA?: typeof qa }).__bennyQA = qa;
221	    if (qs.has('bennyMask')) qa.mask(true);
222	  }
223	
224	  return { root, setExpression, update, radius: 0.8 };
225	}
