227	/**
228	 * Flat ID colours for pixel measurement in real game captures (no lighting, fog or textures):
229	 * body fur / arms / feet / face = red, beanie crown = cyan, ribbed cuff = blue, pom-pom = green, star = black.
230	 * Classify the frame with  R>150,G<60,B<60 (body) · G>150,R<60,B<60 (pom) · B>150,R<60,G<60 (cuff) ·
231	 * R<60,G>150,B>150,|G−B|<40 (crown) · all<40 inside the hat (star).
232	 */
233	const MASK_COLS: [RegExp, string][] = [
234	  [/^fur_pom/, '#00ff00'],
235	  [/^hat_crown/, '#00ffff'],
236	  [/^hat_brim/, '#0000ff'],
237	  [/^hat_star/, '#000000'],
238	];
239	function maskColour(name: string): string {
240	  for (const [re, c] of MASK_COLS) if (re.test(name)) return c;
241	  return '#ff0000';
242	}
243	function setMask(scene: THREE.Object3D, furs: FurHandle[], on: boolean): void {
244	  for (const f of furs) {
245	    f.uniforms.uMaskCol.value.set(maskColour(f.mesh.name));
246	    const d = f.material.defines ?? (f.material.defines = {});
247	    if (on) d.BENNY_MASK = ''; else delete d.BENNY_MASK;
248	    f.material.needsUpdate = true;
249	  }
250	  scene.traverse((o) => {
251	    const m = o as THREE.Mesh;
252	    if (!m.isMesh || (m as unknown as THREE.InstancedMesh).isInstancedMesh) return;
253	    const ud = m.userData as { qaOrig?: THREE.Material | THREE.Material[]; qaVis?: boolean };
254	    if (on && !ud.qaOrig) {
255	      ud.qaOrig = m.material;
256	      ud.qaVis = m.visible;
257	      // face decals sit on the red body: hide them so their alpha edges do not leak texture colours
258	      if (/^(blush|mouth_)/.test(m.name)) m.visible = false;
259	      m.material = new THREE.MeshBasicMaterial({ color: maskColour(m.name), fog: false });
260	    } else if (!on && ud.qaOrig) {
261	      (m.material as THREE.Material).dispose();
262	      m.material = ud.qaOrig;
263	      m.visible = ud.qaVis ?? true;
264	      delete ud.qaOrig;
265	    }
266	  });
267	}
268	function qaInfo(root: THREE.Object3D, body: THREE.Object3D) {
269	  const p = body.getWorldPosition(new THREE.Vector3());
270	  const up = new THREE.Vector3(0, 1, 0).applyQuaternion(root.getWorldQuaternion(new THREE.Quaternion()));
271	  const fwd = new THREE.Vector3(0, 0, 1).applyQuaternion(root.getWorldQuaternion(new THREE.Quaternion()));
272	  const r3 = (v: THREE.Vector3) => v.toArray().map((x) => +x.toFixed(3));
273	  return { body: r3(p), up: r3(up), fwd: r3(fwd), scale: +root.scale.x.toFixed(3) };
274	}
