77	/**
78	 * The crown texture tiles this many times around the beanie (lathe u is scaled by it in build.ts), so the
79	 * stitches stay small: 36 columns × 4 ≈ 144 stitch columns around, as in ref 05 (≈ 6 px stitches on a
80	 * 293 px wide cuff), within the 1024 px texture limit of the GLB export.
81	 */
82	export const CROWN_REPEAT = 4;
83	
84	/** stockinette stitch: two slanted loops forming a "V", colour + height */
85	function knitStitch(ctx: Ctx, hctx: Ctx, cx: number, cy: number, cw: number, rh: number, base: string, mid: string, shade: string) {
86	  for (const side of [-1, 1]) {
87	    const ex = cx + side * cw * 0.21;
88	    const g = ctx.createRadialGradient(ex - side * cw * 0.04, cy - rh * 0.18, 1, ex, cy, cw * 0.36);
89	    g.addColorStop(0, base);
90	    g.addColorStop(0.55, mid);
91	    g.addColorStop(1, shade);
92	    ctx.save();
93	    ctx.translate(ex, cy);
94	    ctx.rotate(side * -0.5);
95	    ctx.beginPath();
96	    ctx.ellipse(0, 0, cw * 0.2, rh * 0.6, 0, 0, Math.PI * 2);
97	    ctx.fillStyle = g;
98	    ctx.fill();
99	    ctx.restore();
100	    const hg = hctx.createRadialGradient(ex, cy, 0, ex, cy, cw * 0.3);
101	    hg.addColorStop(0, '#fff');
102	    hg.addColorStop(0.6, '#9a9a9a');
103	    hg.addColorStop(1, '#151515');
104	    hctx.save();
105	    hctx.translate(ex, cy);
106	    hctx.rotate(side * -0.5);
107	    hctx.beginPath();
108	    hctx.ellipse(0, 0, cw * 0.2, rh * 0.6, 0, 0, Math.PI * 2);
109	    hctx.fillStyle = hg;
110	    hctx.fill();
111	    hctx.restore();
112	  }
113	}
