115	/**
116	 * Knit crown texture (u = around, one of CROWN_REPEAT tiles; v = height 0 bottom → 1 top).
117	 * Stripes bottom→top: white, purple, white, purple, white; with the purple cuff that is 3 purple bands
118	 * (refs 04–10 rear: cuff · W · P · W, the top purple ring shows around the pom-pom, the white top is under it).
119	 */
120	const KNIT_WHITE_HI = '#fffaf8';
121	const KNIT_WHITE = '#fff6f4';
122	const KNIT_WHITE_SHADE = '#c8b2c4';
123	const KNIT_PURPLE_HI = '#8a2cff';
124	const KNIT_PURPLE = BENNY_COLORS.purple;
125	const KNIT_PURPLE_SHADE = BENNY_COLORS.purpleDark;
126	
127	export function knitCrownTextures(): { map: THREE.CanvasTexture; normalMap: THREE.CanvasTexture } {
128	  const W = 1024, Hh = 512;
129	  const [c, ctx] = canvas(W, Hh);
130	  const [hc, hctx] = canvas(W, Hh);
131	  const stripes: [number, number, string, string, string][] = [
132	    // [v0, v1, highlight, base, groove]   (v measured from bottom)
133	    // wave 5 (ref 05 rear, centre column: white 24 / purple 33 / white 19 px, then a purple band around the pom base):
134	    // wider middle purple, thinner upper white, upper purple band starts lower so it shows beside the pom.
135	    // Yarn colours: warmer cream white (live 05 white read lavender #FFD8FF vs ref #F3CFE4) and a stitch highlight
136	    // with less green (live purple stripe #8658FF vs ref #740FF2). A darker yarn (#420cb6, it05) only greyed the stripe
137	    // (#6238B6): its green floor comes from the scene light, so the saturated #7a18f0 yarn stays
138	    [0.0, 0.3, KNIT_WHITE_HI, KNIT_WHITE, KNIT_WHITE_SHADE],
139	    [0.3, 0.58, KNIT_PURPLE_HI, KNIT_PURPLE, KNIT_PURPLE_SHADE],
140	    [0.58, 0.73, KNIT_WHITE_HI, KNIT_WHITE, KNIT_WHITE_SHADE],
141	    [0.73, 0.92, KNIT_PURPLE_HI, KNIT_PURPLE, KNIT_PURPLE_SHADE],
142	    [0.92, 1.0, KNIT_WHITE_HI, KNIT_WHITE, KNIT_WHITE_SHADE],
143	  ];
144	  hctx.fillStyle = '#000';
145	  hctx.fillRect(0, 0, W, Hh);
146	  const cols = 36;
147	  const cw = W / cols;
148	  const rowH = 30; // ≈ 0.025 units per stitch row on the 0.42-unit crown (stitches ≈ as tall as wide)
149	  for (const [v0, v1, hi, base, shade] of stripes) {
150	    const y0 = Hh * (1 - v1), y1 = Hh * (1 - v0);
151	    ctx.fillStyle = shade;
152	    ctx.fillRect(0, y0, W, y1 - y0);
153	    const rows = Math.max(1, Math.round((y1 - y0) / rowH));
154	    const rh = (y1 - y0) / rows;
155	    for (let r = 0; r < rows; r++) {
156	      for (let k = 0; k < cols; k++) knitStitch(ctx, hctx, k * cw + cw / 2, y0 + r * rh + rh / 2, cw, rh, hi, base, shade);
157	    }
158	    // fuzzy yarn speckle
159	    for (let i = 0; i < 3000; i++) {
160	      ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.1})`;
161	      ctx.fillRect(Math.random() * W, y0 + Math.random() * (y1 - y0), 1.5, 1.5);
162	    }
163	  }
164	  return { map: colorTex(c, true), normalMap: normalFromHeight(hc, 4.5, true) };
165	}
166	
167	/** Chunky ribbed (k2p2) folded cuff texture, u around, v across the band: deep grooves + stacked stitches */
168	export function ribbedBrimTextures(): { map: THREE.CanvasTexture; normalMap: THREE.CanvasTexture } {
169	  const W = 1024, Hh = 256;
170	  const [c, ctx] = canvas(W, Hh);
171	  const [hc, hctx] = canvas(W, Hh);
172	  const C = BENNY_COLORS;
173	  const ribs = 64; // ≈ 30 ribs across the visible half, as in ref 05
174	  const rw = W / ribs;
175	  for (let k = 0; k < ribs; k++) {
176	    const x = k * rw;
177	    const g = ctx.createLinearGradient(x, 0, x + rw, 0);
178	    g.addColorStop(0, C.brimDark);
179	    g.addColorStop(0.22, C.brim);
180	    g.addColorStop(0.5, C.purpleLight);
181	    g.addColorStop(0.78, C.brim);
182	    g.addColorStop(1, C.brimDark);
183	    ctx.fillStyle = g;
184	    ctx.fillRect(x, 0, rw, Hh);
185	    const hg = hctx.createLinearGradient(x, 0, x + rw, 0);
186	    hg.addColorStop(0, '#000');
187	    hg.addColorStop(0.5, '#fff');
188	    hg.addColorStop(1, '#000');
189	    hctx.fillStyle = hg;
190	    hctx.fillRect(x, 0, rw, Hh);
191	    // stacked knit "V" stitches along the rib
192	    const rows = 10;
193	    const rh = Hh / rows;
194	    for (let r = 0; r < rows; r++) {
195	      const cy = (r + 0.5) * rh;
196	      for (const side of [-1, 1]) {
197	        ctx.save();
198	        ctx.translate(x + rw / 2 + side * rw * 0.16, cy);
199	        ctx.rotate(side * -0.45);
200	        ctx.fillStyle = 'rgba(175,125,255,0.35)';
201	        ctx.beginPath();
202	        ctx.ellipse(0, 0, rw * 0.17, rh * 0.42, 0, 0, Math.PI * 2);
203	        ctx.fill();
204	        ctx.restore();
205	        hctx.save();
206	        hctx.translate(x + rw / 2 + side * rw * 0.16, cy);
207	        hctx.rotate(side * -0.45);
208	        hctx.fillStyle = 'rgba(255,255,255,0.4)';
209	        hctx.beginPath();
210	        hctx.ellipse(0, 0, rw * 0.17, rh * 0.42, 0, 0, Math.PI * 2);
211	        hctx.fill();
212	        hctx.restore();
213	      }
214	      // dark gap between stacked stitches
215	      ctx.fillStyle = 'rgba(30,0,80,0.35)';
216	      ctx.fillRect(x + rw * 0.2, cy + rh * 0.42, rw * 0.6, rh * 0.12);
217	    }
218	  }
219	  return { map: colorTex(c, true), normalMap: normalFromHeight(hc, 3.6, true) };
220	}
