222	/** Planar eye texture (centre of the canvas = centre of the eye dome). */
223	export function eyeTexture(kind: 'happy' | 'dizzy'): THREE.CanvasTexture {
224	  const S = 256;
225	  const [c, ctx] = canvas(S, S);
226	  const m = S / 2;
227	  // sclera
228	  const sg = ctx.createRadialGradient(m, m * 0.8, 10, m, m, m);
229	  sg.addColorStop(0, '#ffffff');
230	  sg.addColorStop(0.8, '#f3eefc');
231	  sg.addColorStop(1, '#b9a8d8');
232	  ctx.fillStyle = sg;
233	  ctx.fillRect(0, 0, S, S);
234	  if (kind === 'happy') {
235	    // big violet iris
236	    const ir = m * 0.8;
237	    const ig = ctx.createLinearGradient(0, m - ir, 0, m + ir);
238	    ig.addColorStop(0, '#2d0f73');
239	    ig.addColorStop(0.45, '#6a35d6');
240	    ig.addColorStop(1, '#c9a4ff');
241	    ctx.fillStyle = ig;
242	    ctx.beginPath();
243	    ctx.arc(m, m + 4, ir, 0, Math.PI * 2);
244	    ctx.fill();
245	    // iris radial streaks
246	    ctx.strokeStyle = 'rgba(255,255,255,0.10)';
247	    ctx.lineWidth = 2;
248	    for (let a = 0; a < Math.PI * 2; a += 0.18) {
249	      ctx.beginPath();
250	      ctx.moveTo(m + Math.cos(a) * ir * 0.45, m + 4 + Math.sin(a) * ir * 0.45);
251	      ctx.lineTo(m + Math.cos(a) * ir * 0.95, m + 4 + Math.sin(a) * ir * 0.95);
252	      ctx.stroke();
253	    }
254	    ctx.strokeStyle = '#1e0848';
255	    ctx.lineWidth = 7;
256	    ctx.beginPath();
257	    ctx.arc(m, m + 4, ir, 0, Math.PI * 2);
258	    ctx.stroke();
259	    // pupil
260	    ctx.fillStyle = '#10061f';
261	    ctx.beginPath();
262	    ctx.arc(m, m + 6, ir * 0.48, 0, Math.PI * 2);
263	    ctx.fill();
264	    // sparkles: big upper-right, small lower-left
265	    ctx.fillStyle = '#ffffff';
266	    ctx.beginPath();
267	    ctx.ellipse(m + ir * 0.32, m - ir * 0.3, ir * 0.24, ir * 0.2, -0.4, 0, Math.PI * 2);
268	    ctx.fill();
269	    ctx.beginPath();
270	    ctx.arc(m - ir * 0.3, m + ir * 0.38, ir * 0.11, 0, Math.PI * 2);
271	    ctx.fill();
272	    ctx.fillStyle = 'rgba(255,255,255,0.7)';
273	    ctx.beginPath();
274	    ctx.arc(m + ir * 0.05, m + ir * 0.5, ir * 0.06, 0, Math.PI * 2);
275	    ctx.fill();
276	  } else {
277	    // dizzy purple spiral
278	    ctx.strokeStyle = '#5a1fc8';
279	    ctx.lineWidth = 15;
280	    ctx.lineCap = 'round';
281	    ctx.beginPath();
282	    for (let t = 0; t < 6 * Math.PI; t += 0.05) {
283	      const r = (t / (6 * Math.PI)) * m * 0.82;
284	      const x = m + Math.cos(t) * r, y = m + Math.sin(t) * r;
285	      if (t === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
286	    }
287	    ctx.stroke();
288	    ctx.strokeStyle = '#8a55ff';
289	    ctx.lineWidth = 5;
290	    ctx.stroke();
291	  }
292	  // dark rim
293	  ctx.strokeStyle = '#3a1d66';
294	  ctx.lineWidth = 10;
295	  ctx.beginPath();
296	  ctx.arc(m, m, m - 5, 0, Math.PI * 2);
297	  ctx.stroke();
298	  return colorTex(c);
299	}
