301	/** Mouth decal (alpha). 'happy' = open smile, 'dizzy' = round open "O", 'peek' = small grin */
302	export function mouthTexture(kind: 'happy' | 'dizzy' | 'peek'): THREE.CanvasTexture {
303	  const S = 256;
304	  const [c, ctx] = canvas(S, S);
305	  ctx.clearRect(0, 0, S, S);
306	  const m = S / 2;
307	  ctx.save();
308	  ctx.beginPath();
309	  if (kind === 'dizzy') {
310	    ctx.ellipse(m, m, 62, 74, 0, 0, Math.PI * 2);
311	  } else {
312	    const w = kind === 'peek' ? 86 : 104;
